Given a string s, check if it is a Pangram or not.  A Pangram is a sentence containing every letter in the English Alphabet either in lowercase or Uppercase.Examples: Input: s = "The quick brown fox jumps over the lazy dog" Output: trueExplanation: The input string contains all characters from 'a' to 'z'.Input: s = "The quick brown fox jumps over the dog"Output: falseExplanation: The input string does not contain all characters from 'a' to 'z', as 'l', 'z', 'y' are missingTry It YourselfTable of Content[Naive Approach] By Searching for each Character - O(26 * n) Time and O(1) Space[Expected Approach] Using Visited Array - O(n) Time and O(26) Space[Naive Approach] By Searching for each Character - O(26 * n) Time and O(1) SpaceThe idea is to iterate over all characters from 'a' to 'z' and for each character, check if it is present in the input string or not. If any character is not present in the input string, return false. Otherwise, return true. Also, we need to ignore the case while searching for a character('a' and 'A' are considered same).
            C++

    #include <iostream>
#include <algorithm>
using namespace std;

bool checkPangram(string &s) {

    // Check every lowercase letter
    for (char ch = 'a'; ch <= 'z'; ch++) {
        bool found = false;

        // Search for the current letter in the string
        for (int i = 0; i < s.length(); i++) {
            if (ch == tolower(s[i])) {
                found = true;
                break;
            }
        }

        // If any letter is missing, it is not a pangram
        if (!found)
            return false;
    }

    // All letters are present
    return true;
}

int main() {

    string s = "The quick brown fox jumps over the lazy dog";

    if (checkPangram(s))
        cout << "true";
    else
        cout << "false";

    return 0;
}


