            if (c >= 'A' && c <= 'Z')
                vis[c - 'A'] = true;

            // Mark lowercase letters
            else if (c >= 'a' && c <= 'z')
                vis[c - 'a'] = true;
        }

        // Check if all letters are present
        for (int i = 0; i < 26; i++) {
            if (!vis[i])
                return false;
        }

        return true;
    }

    public static void main(String[] args) {
        String s = "The quick brown fox jumps over the lazy dog";
        System.out.println(checkPangram(s) ? "true" : "false");
    }
}


